/* =========================================================================
 * 和风浅色主题（松叶白绿 x 利休白茶）
 * 1) 背景 / 地形 / 摇杆 / 按钮：整图重上色，形状与尺寸不变
 * 2) 角色：只改 node.color，模型与武器一律不动
 * 3) 纯色底与标题字：改 color
 * 开关：?theme=0 关闭；状态：window.__themeV1.report()
 * ========================================================================= */
;(function () {
  'use strict';
  if (/[?&]theme=0/.test(location.search || '')) return;
  if (window.__themeV1) return;

  var IMG = {"bg_forest":"data:image/png;base64,","bg_violet":"data:image/png;base64,","bg_winter":"data:image/png;base64,","bg_space":"data:image/png;base64,","platform_forest":"data:image/png;base64,","platform_violet":"data:image/png;base64,","platform_winter":"data:image/png;base64,","wall_forest":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMElEQVR42u3OIQEAMAgAMHgKFIr+FU8MzJZgOV0/Dr04JiAgICAgICAgICAgICAgsMv1AZmvA6loAAAAAElFTkSuQmCC","wall_violet":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMElEQVR42u3OIQEAMAgAMHgKFIr+FU8MzJZgOV0/Dr04JiAgICAgICAgICAgICAgsMv1AZmvA6loAAAAAElFTkSuQmCC","wall_winter":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMUlEQVR42u3OMQ0AMAgAMJgKLi78S1yQwdMqaE7Xj0MvjgkICAgICAgICAgICAgICCy72QGYbkDAUQAAAABJRU5ErkJggg==","corner_wall_forest":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMElEQVR42u3OQQEAQAQAMC6oIEKofGL4bAmW0/Xj0ItjAgICAgICAgICAgICAgICC6yAAqWpyNVQAAAAAElFTkSuQmCC","corner_wall_violet":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMElEQVR42u3OQQEAQAQAMC6oIEKofGL4bAmW0/Xj0ItjAgICAgICAgICAgICAgICC6yAAqWpyNVQAAAAAElFTkSuQmCC","corner_wall_winter":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMElEQVR42u3OQQEAQAQAMC6oIEKofGL4bAmW0/Xj0ItjAgICAgICAgICAgICAgICC6yAAqWpyNVQAAAAAElFTkSuQmCC","joystick_big":"data:image/png;base64,","joystick_small":"data:image/png;base64,","attackBack":"data:image/png;base64,","btn_green_L":"data:image/png;base64,","btn_violet_L":"data:image/png;base64,","btn_blue_L":"data:image/png;base64,","btn_yellow":"data:image/png;base64,","arena":"data:image/png;base64,","cell_weapon":"data:image/png;base64,","bg_weapon_name":"data:image/png;base64,","icon_settings":"data:image/png;base64,","2_player_icon":"data:image/png;base64,","1_player_icon":"data:image/png;base64,","spikes":"data:image/png;base64,","platform_space":"data:image/png;base64,","wall_space":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMUlEQVR42u3OMQ0AMAgAMJgKLi78S1yQwdMqaE7Xj0MvjgkICAgICAgICAgICAgICCy72QGYbkDAUQAAAABJRU5ErkJggg==","corner_wall_space":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAAMElEQVR42u3OQQEAQAQAMC6oIEKofGL4bAmW0/Xj0ItjAgICAgICAgICAgICAgICC6yAAqWpyNVQAAAAAElFTkSuQmCC"};

  var T = window.__themeV1 = {
    version: 'theme-r1', made: 0, recolored: 0, texts: 0,
    report: function () { return { version: T.version, made: T.made, recolored: T.recolored, texts: T.texts }; }
  };

  var P1_FROM = [8, 178, 232], P1_TO = [62, 110, 142];
  var P2_FROM = [229, 51, 42], P2_TO = [192, 90, 74];
  var SOLID = [
    [[0x1F, 0x5C, 0xA1], [0xE8, 0xE5, 0xC8]],
    [[0x1F, 0x40, 0x91], [0xE9, 0xDF, 0xC9]],
    [[0x11, 0x43, 0x89], [0xC8, 0xC2, 0xAC]]
  ];
  var INK = [0x2E, 0x3A, 0x34];

  var INS = {
    platform_forest: [15, 66, 15, 10], platform_violet: [15, 66, 15, 10],
    platform_winter: [15, 66, 15, 10], platform_space: [15, 66, 15, 10],
    btn_green_L: [20, 20, 20, 20], btn_violet_L: [15, 15, 15, 15], btn_blue_L: [20, 20, 20, 20],
    btn_yellow: [15, 15, 15, 15], arena: [20, 20, 20, 20], bg_weapon_name: [8, 8, 8, 8]
  };

  var cache = {};
  function img(name) {
    if (cache[name]) return cache[name];
    var o = cache[name] = { el: new Image(), done: false };
    o.el.onload = function () { o.done = true; };
    o.el.src = IMG[name];
    return o;
  }
  for (var k in IMG) img(k);

  var NEWF = {};
  function buildFrame(nm) {
    var it = cache[nm];
    if (!it || !it.done || !it.el.width) return null;
    var el = it.el;
    try {
      var tex = new cc.Texture2D();
      tex.initWithElement(el);
      tex.handleLoadedTexture();
      var sf = new cc.SpriteFrame();
      sf.setTexture(tex);
      sf.setRect(cc.rect(0, 0, el.width, el.height));
      sf.setOriginalSize(cc.size(el.width, el.height));
      var ins = INS[nm];
      if (ins) {
        sf.insetLeft = ins[0]; sf.insetTop = ins[1];
        sf.insetRight = ins[2]; sf.insetBottom = ins[3];
      }
      sf.name = nm;
      T.made++;
      return sf;
    } catch (e) { return null; }
  }

  // space 场地没有独立重绘贴图，复用 forest 的木台/墙材质，保证四个场地浅色统一
  var ALIAS = {
    platform_space: "platform_forest",
    wall_space: "wall_forest",
    corner_wall_space: "corner_wall_forest"
  };

  function applySprite(sp) {
    var sf = sp.spriteFrame;
    if (!sf) return;
    var nm = sf.name || sf._name;
    if (nm && !IMG[nm] && ALIAS[nm]) nm = ALIAS[nm];
    if (!nm || !IMG[nm]) return;
    if (NEWF[nm] && sp.spriteFrame === NEWF[nm]) return;
    var nf = NEWF[nm];
    if (!nf) {
      nf = buildFrame(nm);
      if (!nf) return;
      NEWF[nm] = nf;
    }
    sp.spriteFrame = nf;
    if (INS[nm]) sp.type = cc.Sprite.Type.SLICED;
  }

  function eq(c, a) { return c && c.r === a[0] && c.g === a[1] && c.b === a[2]; }

  function underBtn(n) {
    var p = n;
    while (p) {
      var s = p.getComponent && p.getComponent(cc.Sprite);
      if (s && s.spriteFrame) {
        var nm = s.spriteFrame.name || '';
        if (nm.indexOf('btn_') === 0) return true;
        if (nm === 'bg_weapon_name') return true;
      }
      p = p.parent;
    }
    return false;
  }

  function walk(n) {
    var sp = n.getComponent && n.getComponent(cc.Sprite);
    if (sp) applySprite(sp);

    var c = n.color;
    if (c) {
      if (eq(c, P1_FROM)) { n.color = new cc.Color(P1_TO[0], P1_TO[1], P1_TO[2]); T.recolored++; }
      else if (eq(c, P2_FROM)) { n.color = new cc.Color(P2_TO[0], P2_TO[1], P2_TO[2]); T.recolored++; }
      else for (var i = 0; i < SOLID.length; i++) {
        if (eq(c, SOLID[i][0])) { var t = SOLID[i][1]; n.color = new cc.Color(t[0], t[1], t[2]); break; }
      }
      // 浅底上的白字改墨绿
      if (c.r === 255 && c.g === 255 && c.b === 255 && n.getComponent(cc.Label)) {
        if (!underBtn(n)) { n.color = new cc.Color(INK[0], INK[1], INK[2]); T.texts++; }
      }
    }
    var ch = n.children;
    for (var j = 0; j < ch.length; j++) walk(ch[j]);
  }

  // DOM 层（血条 / GUIDE）配色
  function css() {
    if (document.getElementById('__themeCss')) return;
    var st = document.createElement('style');
    st.id = '__themeCss';
    st.textContent = [
      '.hud2bar{background:rgba(250,247,236,.62)!important;border-color:rgba(46,58,52,.62)!important}',
      '.hud2trail{background:rgba(46,58,52,.30)!important}',
      '.hud2fill{background:linear-gradient(180deg,#3E6E8E,#2A4C63)!important}',
      '.hud2card[style*="right"] .hud2fill{background:linear-gradient(180deg,#C05A4A,#8E3F33)!important}',
      '.hud2num{color:#2E3A34!important;text-shadow:0 1px 0 rgba(255,255,255,.6)!important}',
      '.hud2tag{color:#2E3A34!important;text-shadow:0 1px 0 rgba(255,255,255,.55)!important}',
      '#__guideBtnDom{background:#C05A4A!important;border-color:#8E3F33!important;color:#FFF8EC!important}'
    ].join('');
    document.head.appendChild(st);
  }
  css();
  setInterval(css, 800);

  function tick() {
    if (!window.cc || !cc.director) return;
    var sc = cc.director.getScene();
    if (!sc) return;
    try { walk(sc); } catch (e) {}
  }
  setInterval(tick, 150);
  setTimeout(tick, 900);
})();
